import{_ as a,a as r,c as t,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"OBS：生命周期、恢复与故障推演","description":"将保留、恢复、鉴权、结果不明和纸面实践集中呈现。","frontmatter":{"title":"OBS：生命周期、恢复与故障推演","description":"将保留、恢复、鉴权、结果不明和纸面实践集中呈现。","showdocs":{"topics":[{"id":"obs","title":"华为云 OBS","link":"/topics/obs/"}],"kind":"知识专题","scope":"general","audience":"general","group":"数据库与存储","seriesTitle":"OBS 原生对象存储理论与 CLI 阅读","summary":"将保留、恢复、鉴权、结果不明和纸面实践集中呈现。","status":"active","related":[{"title":"OBS 实践：完整原生 Python SDK CLI","link":"/middleware/object-storage/obs/plus/practice/application","kind":"应用实践","scope":"general","audience":"general"},{"title":"OBS：对象身份、权限与版本机制","link":"/middleware/object-storage/obs/object-model","kind":"知识专题","scope":"general","audience":"general"}],"prev":{"text":"OBS 实践：完整原生 Python SDK CLI","link":"/middleware/object-storage/obs/plus/practice/application"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"OBS 实践：完整原生 Python SDK CLI","link":"/middleware/object-storage/obs/plus/practice/application"},"next":false},"headers":[],"relativePath":"middleware/object-storage/obs/recovery.md","filePath":"middleware/object-storage/obs/recovery.md"}'),s={name:"middleware/object-storage/obs/recovery.md"};function i(l,e,p,n,c,d){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="obs-生命周期、恢复与故障推演" tabindex="-1">OBS：生命周期、恢复与故障推演 <a class="header-anchor" href="#obs-生命周期、恢复与故障推演" aria-label="Permalink to &quot;OBS：生命周期、恢复与故障推演&quot;">​</a></h1><h2 id="part-1" tabindex="-1">版本恢复、碎片治理与原生错误排查 <a class="header-anchor" href="#part-1" aria-label="Permalink to &quot;版本恢复、碎片治理与原生错误排查 {#part-1}&quot;">​</a></h2><h3 id="part-1-lifecycle" tabindex="-1">生命周期和容量 <a class="header-anchor" href="#part-1-lifecycle" aria-label="Permalink to &quot;生命周期和容量 {#part-1-lifecycle}&quot;">​</a></h3><p>OBS 生命周期可针对当前版本、历史版本、无历史版本的删除标记和分段碎片分别设置动作。当前版本过期并不必然清除历史内容，标记清理也不等于按业务要求完成数据销毁；对象可能受保留和存储类别条件影响。规则应先对独立前缀评估，并与保留需求一起审查。本系列不写入或启用任何规则。<a href="https://support.huaweicloud.com/usermanual-obs/obs_41_0074.html" target="_blank" rel="noopener noreferrer">官方生命周期配置</a>列出了这些不同对象。</p><p>OBS 生命周期计算还涉及基于 UTC 日期的时间边界与异步执行，不能用“上传后恰好24小时”作为精确承诺。容量清单应分别计当前字节、历史字节和未完成段；低频或归档类别需要评估最短存储期与取回成本。<a href="https://support.huaweicloud.com/intl/zh-cn/usermanual-obs/obs_03_0335.html" target="_blank" rel="noopener noreferrer">官方生命周期概述</a>解释计时方式。业务展示到期由应用控制，不应等物理清理事件触发。</p><h3 id="part-1-restore" tabindex="-1">恢复演练 <a class="header-anchor" href="#part-1-restore" aria-label="Permalink to &quot;恢复演练 {#part-1-restore}&quot;">​</a></h3><p>OBS 恢复先核对多版本是否在误操作前已启用，再区分删除标记遮挡、覆盖产生新版本、永久删掉某一版本以及归档不可立即读取。普通 list 不能替代版本列举，恢复清单应记录 key、versionId、时间、大小与标记状态。先读取选中的旧版本到独立位置、验证摘要，再复制为新的当前版本并保存新版本 ID；恢复者还须避免覆盖业务正在发布的结果。</p><p>如果只是删除当前标记，旧内容可能立即变为当前可见对象，要先核对业务归属与内容；如果指定版本已被永久删除，多版本无法恢复该版本，需要独立副本。恢复验收应同时检查对象字节、数据库引用和访问权限，而不是只在控制台看见名字。</p><h3 id="part-1-diagnostics" tabindex="-1">状态、鉴权和签名排错 <a class="header-anchor" href="#part-1-diagnostics" aria-label="Permalink to &quot;状态、鉴权和签名排错 {#part-1-diagnostics}&quot;">​</a></h3><p>OBS 鉴权排错先记录 status、errorCode、requestId、地域和目标动作。status=403 时检查 AK/SK 是否同一组、security_token 是否匹配且未过期、IAM 与桶策略是否允许、是否存在显式拒绝和 KMS 限制。不要把对象设成公开来绕过问题；SDK 响应成功解析也不代表请求成功。</p><p>OBS 签名排错要核对原生 signature 模式、服务 Endpoint、Host、对象编码与系统时间。<code>createSignedUrl</code> 的签名头和 query 必须与实际请求一致，转发层不可随意改写；临时凭据过期会让 URL 提前失效。仅签名失败或 URL 访问失败都不应直接推导产品不兼容，应先对照<a href="https://support.huaweicloud.com/sdk-python-devg-obs/obs_22_1301.html" target="_blank" rel="noopener noreferrer">原生 URL 参数</a>。工单只留脱敏结构，不粘贴完整能力 URL。</p><h3 id="part-1-retry" tabindex="-1">重试与连接资源 <a class="header-anchor" href="#part-1-retry" aria-label="Permalink to &quot;重试与连接资源 {#part-1-retry}&quot;">​</a></h3><p>OBS 重试必须区分收到非 2xx 响应、传输异常和提交成功但响应丢失。固定 versionId 的只读请求较易安全重试；上传新随机名会产生潜在孤儿对象，不能无限重试。分段上传保留检查点和各段信息，完成请求超时后先核对目标对象，明确放弃时中止任务。GET 流无论成功、异常还是消费者提前停止都要关闭，否则连接池可能耗尽。</p><p>练习：requestId 为什么比异常字符串更关键？答案是它可关联服务端单次请求，而本地属性错误可能只是代码忽略了失败响应。应保留原错误并限制重试次数，既避免放大限流，也避免日志泄漏凭据。本轮排错均为理论推演，示例未执行，没有连接云账号。</p><h2 id="part-2" tabindex="-1">用状态对象与版本号解释正确性 <a class="header-anchor" href="#part-2" aria-label="Permalink to &quot;用状态对象与版本号解释正确性 {#part-2}&quot;">​</a></h2><h3 id="part-2-questions" tabindex="-1">自测场景 <a class="header-anchor" href="#part-2-questions" aria-label="Permalink to &quot;自测场景 {#part-2-questions}&quot;">​</a></h3><p>OBS 复习先回答四题：SDK 没抛异常但 status=403 是否成功？将 Boto3 的 IfMatch 参数传给 ObsClient 能否作为原生条件写？开启多版本是否能防止业务最后写入者覆盖当前引用？分段上传只完成一半为何仍可能计费？前置是<a href="/middleware/object-storage/obs/object-model#part-2">机制</a>与<a href="/middleware/object-storage/obs/plus/practice/application#source">完整源码</a>，先写出对应的状态与资源，再看答案。</p><h3 id="part-2-answers" tabindex="-1">参考答案 <a class="header-anchor" href="#part-2-answers" aria-label="Permalink to &quot;参考答案 {#part-2-answers}&quot;">​</a></h3><p>OBS 状态解答：远端失败通常由 status、errorCode、requestId 表达，传输异常另行处理。应在读取成功 body 前检查状态，错误日志保留 requestId；不是把每个 SDK 都塞进同一 ClientError 捕获就能得到可靠结果。createSignedUrl 又是本地签名结果，不能套用远端响应检查。</p><p>OBS 并发解答：原生接口有自己的参数模型，读取和复制源条件不能推导目标 PUT 的 CAS。UUID 不变对象与数据库发布指针是一种应用设计，真正的幂等和串行化由业务状态合同决定。多版本保留字节历史，却不自动让当前引用符合编辑者意图。版本 ID 应和业务结果一起保存。</p><p>OBS 分段解答：上传任务和已传段可在完整对象尚不存在时占用容量；清理必须中止任务或配置相应生命周期。旧版本、删除标记和归档取回也是不同成本项。只看到 listObjects 为空不能宣布成本为零，更不能宣布所有历史内容永久销毁。<a href="https://support.huaweicloud.com/usermanual-obs/obs_41_0074.html" target="_blank" rel="noopener noreferrer">生命周期官方说明</a>支持这种分类。</p><h3 id="part-2-practice" tabindex="-1">纸面综合实践 <a class="header-anchor" href="#part-2-practice" aria-label="Permalink to &quot;纸面综合实践 {#part-2-practice}&quot;">​</a></h3><p>OBS 实践设计一张上传事件表，字段包括业务请求键、bucket、key、versionId、摘要、requestId 和业务状态。依次推演上传返回403、上传成功后本地进程退出、数据库提交失败、数据库成功但 HTTP 回包丢失。参考处理是：远端拒绝不发布引用；未知结果先核对而不是换 key 重试；未引用对象等待审计清理；业务已提交的请求使用幂等查询返回既有结果。</p><p>再设计一次版本恢复：读取旧版本、比对摘要、复制到新对象或新版本、事务更新发布指针，并保留恢复前状态。若恢复期间有新发布，应报告业务冲突而不是擅自覆盖。纸面验收应说明每个操作是否可逆、是否生成版本或段、费用是否继续。这个练习不用启动任何服务或访问账号。</p><h3 id="part-2-scope" tabindex="-1">完成标准与后续边界 <a class="header-anchor" href="#part-2-scope" aria-label="Permalink to &quot;完成标准与后续边界 {#part-2-scope}&quot;">​</a></h3><p>能区分分发名与导入名、原生签名与兼容模式、status 响应与异常、版本删除与普通删除，能找到 CLI 分页、资源关闭和错误退出，就完成理论路线。读者自行运行还须记录实际 SDK 小版本和原生接口行为，本轮示例未执行、未安装、未连接。并行文件系统、跨区域复制、WORM、细粒度 IAM 和大文件分段性能都需要单独研究，不能用本示例推导生产能力。</p>',26)])])}const b=a(s,[["render",i]]);export{u as __pageData,b as default};
